function(container, apiUrl, tables) {
  // データ取得と初期化
  async function loadDashboardData() {
    try {
      const data = await window.aivicApi.list(0) || tables[0]?.records || [];

      // KPI計算
      const totalOrders = data.length;
      const totalAmount = data.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);
      const activeProjects = data.filter(item => item.status === '進行中' || item.status === '作業中').length;
      const completedProjects = data.filter(item => item.status === '完了').length;
      const completionRate = totalOrders > 0 ? Math.round((completedProjects / totalOrders) * 100) : 0;
      const urgentItems = data.filter(item => item.priority === '高' || item.status === '要対応').length;

      // KPI表示更新
      container.querySelector('[data-testid="kpi-total-orders"]').textContent = totalOrders.toLocaleString();
      container.querySelector('[data-testid="kpi-total-amount"]').textContent = `¥${totalAmount.toLocaleString()}`;
      container.querySelector('[data-testid="kpi-active-projects"]').textContent = activeProjects.toLocaleString();
      container.querySelector('[data-testid="kpi-completion-rate"]').textContent = `${completionRate}%`;
      container.querySelector('#urgent-count').textContent = `${urgentItems}件`;

      // 月別集計
      const monthlyData = {};
      data.forEach(item => {
        if (item.created_at || item.order_date || item.date) {
          const date = item.created_at || item.order_date || item.date;
          const month = date.slice(0, 7); // YYYY-MM
          monthlyData[month] = (monthlyData[month] || 0) + 1;
        }
      });

      // ステータス別集計
      const statusData = {};
      data.forEach(item => {
        const status = item.status || '未設定';
        statusData[status] = (statusData[status] || 0) + 1;
      });

      // チャート描画
      renderMonthlyChart(monthlyData);
      renderStatusChart(statusData);

      // 要対応項目表示
      renderUrgentItems(data.filter(item => item.priority === '高' || item.status === '要対応').slice(0, 5));

      // 最新更新表示
      const recentItems = data
        .sort((a, b) => new Date(b.updated_at || b.created_at || '1970-01-01') - new Date(a.updated_at || a.created_at || '1970-01-01'))
        .slice(0, 5);
      renderRecentUpdates(recentItems);

      // 通知表示
      renderNotifications(data);

    } catch (error) {
      console.error('Dashboard data load error:', error);
    }
  }

  // 月別チャート
  function renderMonthlyChart(monthlyData) {
    const ctx = container.querySelector('#monthly-chart').getContext('2d');
    const months = Object.keys(monthlyData).sort();
    const values = months.map(month => monthlyData[month]);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: months.map(m => m.slice(5)), // MM表示
        datasets: [{
          label: '発注件数',
          data: values,
          borderColor: '#22c55e',
          backgroundColor: 'rgba(34, 197, 94, 0.1)',
          borderWidth: 2,
          fill: true,
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          y: {
            beginAtZero: true,
            grid: { color: 'rgba(255,255,255,0.1)' },
            ticks: { color: '#9fb0d1' }
          },
          x: {
            grid: { color: 'rgba(255,255,255,0.1)' },
            ticks: { color: '#9fb0d1' }
          }
        }
      }
    });
  }

  // ステータス別チャート
  function renderStatusChart(statusData) {
    const ctx = container.querySelector('#status-chart').getContext('2d');
    const labels = Object.keys(statusData);
    const values = Object.values(statusData);
    const colors = ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: values,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: {
              color: '#9fb0d1',
              font: { size: 12 },
              padding: 15
            }
          }
        }
      }
    });
  }

  // 要対応項目表示
  function renderUrgentItems(items) {
    const container_el = container.querySelector('#urgent-items');
    if (items.length === 0) {
      container_el.innerHTML = '<div style="text-align: center; padding: 20px 0; color: var(--text-muted); font-size: 14px;">要対応項目はありません</div>';
      return;
    }

    container_el.innerHTML = items.map(item => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.08);" onclick="window.showScreen('scr-3')">
        <div>
          <div style="font-size: 14px; color: var(--text); margin-bottom: 2px;">${item.title || item.name || item.project_name || 'タイトル未設定'}</div>
          <div style="font-size: 12px; color: var(--text-muted);">${item.status || '状態不明'}</div>
        </div>
        <div style="background: #ef4444; color: #fff; font-size: 10px; padding: 2px 6px; border-radius: 4px;">緊急</div>
      </div>
    `).join('');
  }

  // 最新更新表示
  function renderRecentUpdates(items) {
    const container_el = container.querySelector('#recent-updates');
    if (items.length === 0) {
      container_el.innerHTML = '<div style="text-align: center; padding: 20px 0; color: var(--text-muted); font-size: 14px;">更新履歴がありません</div>';
      return;
    }

    container_el.innerHTML = items.map(item => {
      const updateDate = item.updated_at || item.created_at || '';
      const displayDate = updateDate ? new Date(updateDate).toLocaleDateString('ja-JP', { month: 'short', day: 'numeric' }) : '';

      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.08);" onclick="window.showScreen('scr-3')">
          <div>
            <div style="font-size: 14px; color: var(--text); margin-bottom: 2px;">${item.title || item.name || item.project_name || 'タイトル未設定'}</div>
            <div style="font-size: 12px; color: var(--text-muted);">${item.status || '状態不明'}</div>
          </div>
          <div style="font-size: 12px; color: var(--text-muted);">${displayDate}</div>
        </div>
      `;
    }).join('');
  }

  // 通知表示
  function renderNotifications(data) {
    const container_el = container.querySelector('#notifications');
    const notifications = [];

    // 期限切れ項目
    const overdue = data.filter(item => {
      if (item.due_date || item.deadline) {
        const dueDate = new Date(item.due_date || item.deadline);
        return dueDate < new Date();
      }
      return false;
    });

    if (overdue.length > 0) {
      notifications.push({
        type: 'error',
        message: `期限切れの項目が${overdue.length}件あります`,
        action: () => window.showScreen('scr-2')
      });
    }

    // 承認待ち
    const pending = data.filter(item => item.status === '承認待ち' || item.status === '確認待ち');
    if (pending.length > 0) {
      notifications.push({
        type: 'warning',
        message: `承認待ちの項目が${pending.length}件あります`,
        action: () => window.showScreen('scr-2')
      });
    }

    if (notifications.length === 0) {
      container_el.innerHTML = '<div style="text-align: center; padding: 20px 0; color: var(--text-muted); font-size: 14px;">新しい通知はありません</div>';
      return;
    }

    container_el.innerHTML = notifications.map(notif => {
      const bgColor = notif.type === 'error' ? 'rgba(239, 68, 68, 0.1)' : 'rgba(245, 158, 11, 0.1)';
      const borderColor = notif.type === 'error' ? '#ef4444' : '#f59e0b';

      return `
        <div style="background: ${bgColor}; border-left: 3px solid ${borderColor}; padding: 12px; margin-bottom: 8px; border-radius: 4px; cursor: pointer;" onclick="notif.action && notif.action()">
          <div style="font-size: 14px; color: var(--text);">${notif.message}</div>
        </div>
      `;
    }).join('');
  }

  // 初期データ読み込み
  loadDashboardData();

  // 定期更新（5分間隔）
  setInterval(loadDashboardData, 300000);
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortField = '';
  let sortDirection = 'asc';

  // 1. テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#project-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center py-8" style="color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const statusColor = getStatusColor(r.status || '');
      const priorityColor = getPriorityColor(r.priority || '');
      const progress = r.progress || 0;

      return `
        <tr data-id="${r.id}" class="border-b hover:bg-opacity-50 cursor-pointer" style="border-color: rgba(255,255,255,0.08);" onclick="window.showScreen('scr-3')">
          <td class="py-3 px-4">
            <div class="font-medium" style="color: var(--text);">${r.projectName || ''}</div>
            <div class="text-xs mt-1" style="color: var(--text-muted);">${r.description || ''}</div>
          </td>
          <td class="py-3 px-4" style="color: var(--text);">${r.vendor || ''}</td>
          <td class="py-3 px-4">
            <span class="px-2 py-1 text-xs font-medium rounded-full" style="background: ${statusColor}; color: #fff;">
              ${r.status || ''}
            </span>
          </td>
          <td class="py-3 px-4">
            <span class="px-2 py-1 text-xs font-medium rounded-full" style="background: ${priorityColor}; color: #fff;">
              ${r.priority || ''}
            </span>
          </td>
          <td class="py-3 px-4" style="color: var(--text);">¥${(r.budget || 0).toLocaleString()}</td>
          <td class="py-3 px-4" style="color: var(--text);">${formatDate(r.startDate)}</td>
          <td class="py-3 px-4">
            <div class="flex items-center gap-2">
              <div class="flex-1 h-2 rounded-full" style="background: rgba(255,255,255,0.1);">
                <div class="h-full rounded-full" style="background: var(--primary); width: ${progress}%;"></div>
              </div>
              <span class="text-xs" style="color: var(--text-muted);">${progress}%</span>
            </div>
          </td>
          <td class="py-3 px-4 text-center">
            <div class="flex gap-1 justify-center">
              <button class="action-btn secondary edit-btn" data-id="${r.id}" onclick="event.stopPropagation(); window.showScreen('scr-3');">編集</button>
              <button class="action-btn secondary delete-btn" data-id="${r.id}" onclick="event.stopPropagation();">削除</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // KPI更新関数
  function updateKPIs(rows) {
    const total = rows.length;
    const active = rows.filter(r => ['企画中', '設計中', '開発中', 'テスト中'].includes(r.status)).length;
    const completed = rows.filter(r => r.status === '完了').length;
    const totalBudget = rows.reduce((sum, r) => sum + (r.budget || 0), 0);

    container.querySelector('#kpi-total').textContent = total;
    container.querySelector('#kpi-active').textContent = active;
    container.querySelector('#kpi-completed').textContent = completed;
    container.querySelector('#kpi-budget').textContent = `¥${totalBudget.toLocaleString()}`;
  }

  // ユーティリティ関数
  function getStatusColor(status) {
    const colors = {
      '企画中': '#6b7280',
      '設計中': '#f59e0b',
      '開発中': '#10b981',
      'テスト中': '#3b82f6',
      '完了': '#059669',
      '保留': '#ef4444'
    };
    return colors[status] || '#6b7280';
  }

  function getPriorityColor(priority) {
    const colors = {
      '高': '#ef4444',
      '中': '#f59e0b',
      '低': '#10b981'
    };
    return colors[priority] || '#6b7280';
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 2. 初期データ表示
  currentData = tables[0]?.records || [];
  renderRows(currentData);
  updateKPIs(currentData);

  // データを最新に更新
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      currentData = rows;
      renderRows(currentData);
      updateKPIs(currentData);
    }
  });

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const statusFilter = container.querySelector('#filter-status').value;
    const priorityFilter = container.querySelector('#filter-priority').value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    let filtered = rows.filter(r => {
      const matchKeyword = !keyword || 
        (r.projectName || '').toLowerCase().includes(keyword) ||
        (r.vendor || '').toLowerCase().includes(keyword) ||
        (r.description || '').toLowerCase().includes(keyword);

      const matchStatus = !statusFilter || r.status === statusFilter;
      const matchPriority = !priorityFilter || r.priority === priorityFilter;

      return matchKeyword && matchStatus && matchPriority;
    });

    currentData = filtered;
    renderRows(filtered);
    updateKPIs(filtered);
  });

  // 4. ソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      const field = sortHeader.dataset.sort;
      if (sortField === field) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortField = field;
        sortDirection = 'asc';
      }

      const sorted = [...currentData].sort((a, b) => {
        let aVal = a[field] || '';
        let bVal = b[field] || '';

        if (field === 'budget') {
          aVal = parseFloat(aVal) || 0;
          bVal = parseFloat(bVal) || 0;
        } else if (field === 'startDate') {
          aVal = new Date(aVal);
          bVal = new Date(bVal);
        }

        if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
        return 0;
      });

      renderRows(sorted);
    }
  });

  // 5. 削除機能（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この案件を削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const rows = await window.aivicApi.list(0);
      if (rows) {
        currentData = rows;
        renderRows(rows);
        updateKPIs(rows);
      }
    }
  });

  // 6. CSVエクスポート機能
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['案件名', '発注先', 'ステータス', '優先度', '予算', '開始日', '進捗', '説明'];
    const csvData = [
      headers.join(','),
      ...rows.map(r => [
        `"${(r.projectName || '').replace(/"/g, '""')}"`,
        `"${(r.vendor || '').replace(/"/g, '""')}"`,
        `"${(r.status || '').replace(/"/g, '""')}"`,
        `"${(r.priority || '').replace(/"/g, '""')}"`,
        r.budget || 0,
        `"${r.startDate || ''}"`,
        r.progress || 0,
        `"${(r.description || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `web発注プラットフォーム案件一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  let currentProjectId = null;

  // URLパラメータからプロジェクトIDを取得（実際の実装では画面遷移時に渡される）
  const urlParams = new URLSearchParams(window.location.search);
  currentProjectId = urlParams.get('id') || (tables[0].records && tables[0].records[0] ? tables[0].records[0].id : 1);

  // プロジェクトデータを表示する関数
  function displayProject(project) {
    if (!project) return;

    // 基本情報表示部分の更新
    container.querySelector("#display-project-name").textContent = project.projectName || project.name || "";
    container.querySelector("#display-budget").textContent = project.budget ? `¥${Number(project.budget).toLocaleString()}` : "";
    container.querySelector("#display-start-date").textContent = project.startDate || "";
    container.querySelector("#display-end-date").textContent = project.endDate || "";
    container.querySelector("#display-manager").textContent = project.manager || "";

    // ステータス表示の更新
    const statusEl = container.querySelector("#display-status");
    const statusMap = {
      'planning': { text: '計画中', color: '#6b7280' },
      'in-progress': { text: '進行中', color: '#10b981' },
      'review': { text: 'レビュー中', color: '#f59e0b' },
      'completed': { text: '完了', color: '#3b82f6' },
      'cancelled': { text: '中止', color: '#ef4444' }
    };
    const status = statusMap[project.status] || { text: '不明', color: '#6b7280' };
    statusEl.textContent = status.text;
    statusEl.style.background = status.color;

    // 編集フォームの値を設定
    container.querySelector("#edit-project-name").value = project.projectName || project.name || "";
    container.querySelector("#edit-status").value = project.status || "";
    container.querySelector("#edit-budget").value = project.budget || "";
    container.querySelector("#edit-start-date").value = project.startDate || "";
    container.querySelector("#edit-end-date").value = project.endDate || "";
    container.querySelector("#edit-manager").value = project.manager || "";
    container.querySelector("#edit-priority").value = project.priority || "";
    container.querySelector("#edit-description").value = project.description || "";
  }

  // 初期データの読み込み
  async function loadProject() {
    try {
      const projects = await window.aivicApi.list(0);
      if (projects) {
        const project = projects.find(p => p.id == currentProjectId) || projects[0];
        if (project) {
          displayProject(project);
        }
      }
    } catch (error) {
      console.error('プロジェクトデータの読み込みに失敗しました:', error);
      // 初期データがある場合はそれを使用
      if (tables[0].records && tables[0].records.length > 0) {
        displayProject(tables[0].records[0]);
      }
    }
  }

  // 保存ボタンのイベントリスナー
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const formData = {
      projectName: container.querySelector("#edit-project-name").value,
      status: container.querySelector("#edit-status").value,
      budget: container.querySelector("#edit-budget").value,
      startDate: container.querySelector("#edit-start-date").value,
      endDate: container.querySelector("#edit-end-date").value,
      manager: container.querySelector("#edit-manager").value,
      priority: container.querySelector("#edit-priority").value,
      description: container.querySelector("#edit-description").value
    };

    try {
      const updated = await window.aivicApi.update(0, currentProjectId, formData);
      if (updated) {
        displayProject(updated);
        alert('プロジェクト情報を更新しました');
      } else {
        alert('更新に失敗しました');
      }
    } catch (error) {
      console.error('更新エラー:', error);
      alert('更新中にエラーが発生しました');
    }
  });

  // キャンセルボタンのイベントリスナー
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    loadProject(); // 元のデータを再読み込み
  });

  // 戻るボタンのイベントリスナー
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-2"); // Web発注プラットフォームの構築データ一覧
  });

  // 関連ボタンのイベントリスナー
  container.querySelector("#btn-view-tasks").addEventListener("click", () => {
    window.showScreen("scr-1"); // ダッシュボード
  });

  container.querySelector("#btn-view-files").addEventListener("click", () => {
    window.showScreen("scr-4"); // 設定画面
  });

  container.querySelector("#btn-view-history").addEventListener("click", () => {
    window.showScreen("scr-2"); // データ一覧
  });

  // 初期データの読み込み実行
  loadProject();
}
